var postProcessManifests = require('../post-process-manifest');

test('postProcessManifests loads manifests', function (t) {
    copyRecursiveSync(realSamples, copySamples);
    t.plan(1);

    postProcessManifests(
        {
            outdir: copySamples,
            bundles: [
                {
                    bundleName: 'minimal',
                    manifest: 'minimal.manifest.json',
                },
            ],
        },
        t.error
    );
